import{z as B,x as d,o as n,c as A,q as o,j as r,D as e,d as t,s,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"公司金融的实证识别","description":"","frontmatter":{"title":"公司金融的实证识别","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/corporate-finance-identification.md","filePath":"econ/corporate-finance-identification.md","lastUpdated":1791063341000}'),p={name:"econ/corporate-finance-identification.md"};function c(m,a,h,f,D,u){const i=d("Mermaid");return n(),A("div",null,[a[2]||(a[2]=o('<h1 id="公司金融的实证识别" tabindex="-1">公司金融的实证识别 <a class="header-anchor" href="#公司金融的实证识别" aria-label="Permalink to &quot;公司金融的实证识别&quot;">​</a></h1><div class="epigraph"><p>杠杆、投资与治理同时被同一未观测冲击驱动。没有设计，回归只是条件相关。</p><footer>—— 对照 Angrist–Pischke 的设计语言；公司金融里 Rajan–Zingales、自然实验与 IV 的传统</footer></div><p><a href="/econ/family-firms-pyramids">上一课</a>把 \\(V\\neq C\\) 写成结构。本课收束「公司金融进阶」：以后凡写「治理导致价值」，要能指出冲击从哪来。一般识别语言要从后面的<a href="/econ/potential-outcomes">潜在结果</a>一课才展开；这里只补公司金融特有的内生性，不把 Rubin 模型提前推一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>投资对 \\(q\\) 的回归、杠杆对利润的回归、独董对绩效的回归，都有反向因果与遗漏变量。自然实验：税法、管制、指数纳入、破产法庭、银行分支放松。IV 弱与排斥限制在公司治理里尤其脆（「法律起源」当 IV 的争论）。缺口是把本课程已有机制（权衡、优序、代理、控制权）映射到可辩护的设计，而不是再开一门计量。</p><p><span class="marginnote">术语翻译：「反向因果」就是箭头画反了——不是独董多让公司变好，而是预期变好的公司才去请独董；「遗漏变量」则是第三个因素（如管理层质量）同时推动杠杆与绩效，回归却把它漏掉了。两者都让系数变成「相关」而非「因果」。</span></p><p><span class="marginnote">Rajan and Zingales, <em>AER</em> 1998：依赖外部融资的行业 × 金融发展。Bertrand and Schoar 的经理人风格。Roberts and Whited 对公司金融识别的综述。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先写反事实：同一家企业若治理/融资不同会怎样。再找使该差异近乎随机的冲击，并论证只经宣称渠道。差分：政策在时间与截面的交错。匹配与固定效应不能替代设计，只能减噪。与金字塔：控制权内生，用继承、创始人死亡等要非常小心排斥。与 ESG：评级机构方法论变更或强制披露，好过把 ESG 分数当外生。</p><p><span class="marginnote">直觉类比：好的工具变量像掷骰子——骰子点数与企业质量毫无关系，却随机决定谁受处理。只要骰子除「决定谁被处理」之外没有别的通道影响结果（排斥限制），它带来的变动就能当作因果来用。</span></p>',10)),(n(),r(l,null,{default:e(()=>[s(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E5%A4%96%E7%94%9F%E5%86%B2%E5%87%BB%22%5D%20--%3E%20D%5B%22%E8%9E%8D%E8%B5%84%20%2F%20%E6%B2%BB%E7%90%86%22%5D%0A%20%20D%20--%3E%20Y%5B%22%E6%8A%95%E8%B5%84%20%2F%20%E4%BB%B7%E5%80%BC%22%5D%0A%20%20U%5B%22%E6%9C%AA%E8%A7%82%E6%B5%8B%E5%86%B2%E5%87%BB%22%5D%20--%3E%20D%0A%20%20U%20--%3E%20Y%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"识别失败时，系数是选择与因果的混合物。例如高 \\(q\\) 企业多投资，把 \\(q\\) 当因果是把信息与机会混在一起。好的设计把 \\(D\\) 的外生部分分离出来，对应本课程某一条机制（税盾、债务约束、控制权私人收益）。",-1)),(n(),r(l,null,{default:e(()=>[s(i,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E6%94%BF%E7%AD%96%E5%86%B2%E5%87%BB%EF%BC%9A%E7%A8%8E%E6%B3%95%20%2F%20%E7%AE%A1%E5%88%B6%22%5D%20--%3E%20B%5B%22%E5%A4%84%E7%90%86%E7%BB%84%EF%BC%9A%E5%8F%97%E5%BD%B1%E5%93%8D%E4%BC%81%E4%B8%9A%22%5D%0A%20%20A%20--%3E%20C%5B%22%E5%AF%B9%E7%85%A7%E7%BB%84%EF%BC%9A%E6%9C%AA%E5%8F%97%E5%BD%B1%E5%93%8D%E4%BC%81%E4%B8%9A%22%5D%0A%20%20B%20--%3E%20D%5B%22%E6%94%BF%E7%AD%96%E5%89%8D%E5%90%8E%E5%B7%AE%E5%88%86%22%5D%0A%20%20C%20--%3E%20E%5B%22%E6%94%BF%E7%AD%96%E5%89%8D%E5%90%8E%E5%B7%AE%E5%88%86%22%5D%0A%20%20D%20--%3E%20F%5B%22%E5%8F%8C%E9%87%8D%E5%B7%AE%E5%88%86%20%3D%20%E5%9B%A0%E6%9E%9C%E6%95%88%E5%BA%94%22%5D%0A%20%20E%20--%3E%20F%0A%20%20G%5B%22%E5%B9%B3%E8%A1%8C%E8%B6%8B%E5%8A%BF%E6%A3%80%E9%AA%8C%22%5D%20--%3E%20F%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">数字实例：政策后处理组投资率从 10% 升到 13%，同期对照组从 8% 升到 9%。双重差分 \\(=(13\\%-10\\%)-(9\\%-8\\%)=2\\%\\)，把全市场共同上行的 1% 从处理组的变化里减掉，剩下的才是政策的功劳。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不发明新的 IV。聚类、弱 IV、双重差分平行趋势交给下一课程计量课序。贸易课序的跨国比较是另一套外生性（中国冲击等）。公司金融补层在此封口；一般识别语言留给后面的<a href="/econ/potential-outcomes">潜在结果</a>一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>公司金融实证必须先有设计，再谈机制是哪一条。</li><li>治理与杠杆的回归默认有反向因果。</li><li>出处：Roberts and Whited 识别综述；Rajan–Zingales 1998；Angrist–Pischke 设计语言。</li></ul>',5))])}const F=B(p,[["render",c]]);export{C as __pageData,F as default};
